export const additionalKnowledge: Knowledge[] = entries
  .trim()
  .split("\n")
  .map((line) => {
    const [id, category, title, expressions, answer, step, reference] =
      line.split("|");
    return {
      id,
      category,
      title,
      phrases: expressions.split("~"),
      keywords: title.toLowerCase().split(/\s+/),
      answer,
      steps: [step],
      followups: ["Give me the steps", "Make that shorter"],
      related: [],
      reference,
      reviewed: "2026-10-24",
    };
  });
